 "content": "def transform(grid):
    # Treat each separated same-color figure as a binary mask, align their
    # bounding-box origins, and XOR the masks to reveal the common composite.
    h, w = len(grid), len(grid[0])
    color = max((v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    pts = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == color}
    comps=[]
    while pts:
        seed=pts.pop(); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in pts:
                    pts.remove(q); comp.add(q); stack.append(q)
        comps.append(comp)
    masks=[]
    for comp in comps:
        r0=min(r for r,c in comp); r1=max(r for r,c in comp)
        c0=min(c for r,c in comp); c1=max(c for r,c in comp)
        masks.append({(r-r0,c-c0) for r,c in comp})
    H=max(r for m in masks for r,c in m)+1
    W=max(c for m in masks for r,c in m)+1
    out=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if sum((r,c) in m for m in masks)%2:
                out[r][c]=color
    return out
